-- A director may move an enrollment to a newer published version (REQ-MUL-011). Its completions and feedback keep the
-- version they were recorded on, so they now reference the enrollment alone, not the enrollment's current version.
ALTER TABLE "audit_event" DROP CONSTRAINT "audit_action";--> statement-breakpoint
ALTER TABLE "assignment_feedback" DROP CONSTRAINT "assignment_feedback_enrollment";
--> statement-breakpoint
ALTER TABLE "enrollment_milestone" DROP CONSTRAINT "enrollment_milestone_enrollment";
--> statement-breakpoint
DROP INDEX "assignment_feedback_enrollment_idx";--> statement-breakpoint
ALTER TABLE "assignment_feedback" ADD CONSTRAINT "assignment_feedback_enrollment" FOREIGN KEY ("enrollment_id","organization_id") REFERENCES "development_enrollment"("id","organization_id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
